# Define a function to find the smallest prime factor of a number
def smallest_prime_factor(n):
    for i in range(2, sp.sqrt(n) + 1):
        if n % i == 0:
            return i
    return n

# Function to count the number of divisors
def count_divisors(n):
    return sp.divisor_count(n)

# Initialize a count for sparkly numbers
count = 0

# Iterate through numbers from 2 to 2003
for n in range(2, 2004):
    # Find the smallest prime factor
    d = smallest_prime_factor(n)

    # Check if d is equal to the number of divisors
    if d == count_divisors(n):
        count += 1

