import sympy as sp

# Function to check if a number is sparkly
def is_sparkly(n):
    if n == 1:
        return False
    d = n
    for i in range(2, sp.sqrt(n) + 1):
        if n % i == 0:
            d = i
            break
    return d == sp.divisor_count(n)

# Count sparkly numbers from 2 to 2003
count = sum(is_sparkly(n) for n in range(2, 2004))

print(count)
